// ──────────────────────────── tests ──────────────────────────────────────

test('finds a pair sitting in the middle of the array', () => {
  eq(pairWithTargetSum([1, 2, 4, 6, 8, 9], 14), [3, 4]);
});

test('finds a pair made of the two ends', () => {
  eq(pairWithTargetSum([2, 3], 5), [0, 1]);
});

test('works with negative numbers', () => {
  eq(pairWithTargetSum([-5, -2, 0, 3, 7], 1), [1, 3]);
});

test('returns null when no pair reaches the target', () => {
  eq(pairWithTargetSum([1, 2, 3, 4], 100), null);
});

test('never uses the same element twice', () => {
  eq(pairWithTargetSum([1, 2, 3], 6), null);
});

test('handles duplicate values', () => {
  eq(pairWithTargetSum([3, 3], 6), [0, 1]);
});

test('handles empty and single-element arrays', () => {
  eq(pairWithTargetSum([], 7), null);
  eq(pairWithTargetSum([4], 8), null);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('reverseInPlace flips an even-length array', () => {
  eq(reverseInPlace([1, 2, 3, 4]), [4, 3, 2, 1]);
});

test('reverseInPlace flips an odd-length array', () => {
  eq(reverseInPlace(['a', 'b', 'c']), ['c', 'b', 'a']);
});

test('reverseInPlace mutates the array it was handed', () => {
  const arr = [1, 2, 3];
  const out = reverseInPlace(arr);
  ok(out === arr, 'should return the same array reference');
  eq(arr, [3, 2, 1]);
});

test('reverseInPlace copes with empty and single-element arrays', () => {
  eq(reverseInPlace([]), []);
  eq(reverseInPlace([7]), [7]);
});

test('rotateRight moves the tail to the front', () => {
  eq(rotateRight([1, 2, 3, 4, 5], 2), [4, 5, 1, 2, 3]);
});

test('rotateRight wraps when k is bigger than the array', () => {
  eq(rotateRight([1, 2, 3], 5), [2, 3, 1]);
});

test('rotateRight with k = 0 changes nothing', () => {
  eq(rotateRight([1, 2, 3], 0), [1, 2, 3]);
});

test('rotateRight works in place and survives an empty array', () => {
  const arr = [1, 2, 3, 4];
  ok(rotateRight(arr, 1) === arr, 'should return the same array reference');
  eq(arr, [4, 1, 2, 3]);
  eq(rotateRight([], 3), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('ignores punctuation, spaces and case', () => {
  eq(isPalindrome('A man, a plan, a canal: Panama'), true);
});

test('rejects text that is not a palindrome', () => {
  eq(isPalindrome('race a car'), false);
});

test('handles a longer sentence with mixed case', () => {
  eq(isPalindrome('Was it a car or a cat I saw?'), true);
});

test('treats digits as real characters', () => {
  eq(isPalindrome('1a2!2a1'), true);
  eq(isPalindrome('12a21b'), false);
});

test('empty text and single characters are palindromes', () => {
  eq(isPalindrome(''), true);
  eq(isPalindrome('x'), true);
});

test('a string of pure punctuation is a palindrome', () => {
  eq(isPalindrome('.,;!'), true);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns the count of unique values', () => {
  eq(removeDuplicates([1, 1, 2]), 2);
});

test('packs the unique values into the front of the array', () => {
  const nums = [0, 0, 1, 1, 1, 2, 2, 3, 3, 4];
  const count = removeDuplicates(nums);
  eq(count, 5);
  eq(nums.slice(0, count), [0, 1, 2, 3, 4]);
});

test('leaves an already-unique array alone', () => {
  const nums = [1, 2, 3];
  eq(removeDuplicates(nums), 3);
  eq(nums, [1, 2, 3]);
});

test('collapses an all-same array to one value', () => {
  const nums = [7, 7, 7, 7];
  eq(removeDuplicates(nums), 1);
  eq(nums[0], 7);
});

test('handles empty and single-element arrays', () => {
  eq(removeDuplicates([]), 0);
  eq(removeDuplicates([9]), 1);
});

test('keeps negatives and a duplicate run at the very end', () => {
  const nums = [-3, -3, -1, 0, 0, 0];
  const count = removeDuplicates(nums);
  eq(count, 3);
  eq(nums.slice(0, count), [-3, -1, 0]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('interleaves two arrays of the same length', () => {
  eq(mergeSorted([1, 3, 5], [2, 4, 6]), [1, 2, 3, 4, 5, 6]);
});

test('drains whichever array still has values left', () => {
  eq(mergeSorted([1, 2, 3], [10]), [1, 2, 3, 10]);
  eq(mergeSorted([10], [1, 2, 3]), [1, 2, 3, 10]);
});

test('handles one empty array on either side', () => {
  eq(mergeSorted([], [1, 2]), [1, 2]);
  eq(mergeSorted([1, 2], []), [1, 2]);
});

test('handles two empty arrays', () => {
  eq(mergeSorted([], []), []);
});

test('keeps duplicates from both sides', () => {
  eq(mergeSorted([1, 1, 2], [1, 3]), [1, 1, 1, 2, 3]);
});

test('works with negative numbers', () => {
  eq(mergeSorted([-3, -1], [-2, 0]), [-3, -2, -1, 0]);
});

test('does not modify the inputs', () => {
  const a = [1, 2];
  const b = [3];
  mergeSorted(a, b);
  eq(a, [1, 2]);
  eq(b, [3]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('finds the best window in the middle', () => {
  eq(maxWindowSum([2, 1, 5, 1, 3, 2], 3), 9);
});

test('finds the best window at the front', () => {
  eq(maxWindowSum([2, 3, 4, 1, 5], 2), 7);
});

test('k equal to the length sums the whole array', () => {
  eq(maxWindowSum([1, 2, 3], 3), 6);
});

test('k of 1 returns the largest single number', () => {
  eq(maxWindowSum([4, 9, 2], 1), 9);
});

test('works when every number is negative', () => {
  eq(maxWindowSum([-1, -2, -3, -4], 2), -3);
});

test('returns 0 when the window does not fit', () => {
  eq(maxWindowSum([1, 2], 5), 0);
  eq(maxWindowSum([], 1), 0);
});

test('returns 0 for a non-positive k', () => {
  eq(maxWindowSum([1, 2, 3], 0), 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('finds the longest repeat-free run', () => {
  eq(longestUnique('abcabcbb'), 3);
});

test('an all-same string has a run of 1', () => {
  eq(longestUnique('bbbbb'), 1);
});

test('the window must be contiguous, not a subsequence', () => {
  eq(longestUnique('pwwkew'), 3);
});

test('never drags the left edge backwards', () => {
  eq(longestUnique('abba'), 2);
});

test('handles a repeat that sits outside the window', () => {
  eq(longestUnique('dvdf'), 3);
});

test('an all-unique string is its own answer', () => {
  eq(longestUnique('abcdef'), 6);
});

test('handles empty and single-character strings', () => {
  eq(longestUnique(''), 0);
  eq(longestUnique('a'), 1);
});

test('counts spaces and punctuation as characters', () => {
  eq(longestUnique('a b a'), 3);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('finds a two-element window', () => {
  eq(smallestSubarrayWithSum([2, 1, 5, 2, 3, 2], 7), 2);
});

test('prefers a single element that already clears the target', () => {
  eq(smallestSubarrayWithSum([2, 1, 5, 2, 8], 7), 1);
});

test('shrinks as far as it can, not just one step', () => {
  eq(smallestSubarrayWithSum([3, 4, 1, 1, 6], 8), 3);
});

test('returns 0 when the whole array is too small', () => {
  eq(smallestSubarrayWithSum([1, 1, 1], 10), 0);
});

test('the whole array can be the answer', () => {
  eq(smallestSubarrayWithSum([1, 2, 3], 6), 3);
});

test('a sum exactly equal to the target counts', () => {
  eq(smallestSubarrayWithSum([4, 3], 3), 1);
});

test('handles empty and single-element arrays', () => {
  eq(smallestSubarrayWithSum([], 5), 0);
  eq(smallestSubarrayWithSum([10], 5), 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('isAnagram accepts a rearrangement', () => {
  eq(isAnagram('listen', 'silent'), true);
});

test('isAnagram rejects different letters', () => {
  eq(isAnagram('rat', 'car'), false);
});

test('isAnagram compares counts, not just which letters appear', () => {
  eq(isAnagram('aabb', 'abab'), true);
  eq(isAnagram('aabb', 'abbb'), false);
});

test('isAnagram rejects different lengths early', () => {
  eq(isAnagram('aa', 'a'), false);
});

test('isAnagram says two empty strings match', () => {
  eq(isAnagram('', ''), true);
});

test('firstNonRepeating finds the single character', () => {
  eq(firstNonRepeating('swiss'), 'w');
});

test('firstNonRepeating returns null when everything repeats', () => {
  eq(firstNonRepeating('aabbcc'), null);
});

test('firstNonRepeating handles empty and single-character text', () => {
  eq(firstNonRepeating(''), null);
  eq(firstNonRepeating('x'), 'x');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('majorityElement finds a value in more than half the slots', () => {
  eq(majorityElement([3, 3, 4, 2, 3, 3, 3]), 3);
});

test('majorityElement returns null when nothing dominates', () => {
  eq(majorityElement([1, 2, 3]), null);
});

test('majorityElement rejects an exact half', () => {
  eq(majorityElement([1, 1, 2, 2]), null);
});

test('majorityElement handles empty and single-element arrays', () => {
  eq(majorityElement([]), null);
  eq(majorityElement([5]), 5);
});

test('topKFrequent ranks by count, most frequent first', () => {
  eq(topKFrequent(['a', 'b', 'a', 'c', 'b', 'a'], 2), ['a', 'b']);
  eq(topKFrequent(['a', 'b', 'a', 'c', 'b', 'a'], 1), ['a']);
});

test('topKFrequent breaks ties by first appearance', () => {
  eq(topKFrequent(['x', 'y', 'z'], 2), ['x', 'y']);
});

test('topKFrequent caps at the number of distinct values', () => {
  eq(topKFrequent(['a', 'a', 'b'], 5), ['a', 'b']);
});

test('topKFrequent handles an empty input and k of 0', () => {
  eq(topKFrequent([], 3), []);
  eq(topKFrequent(['a'], 0), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('binarySearch finds a value in the middle', () => {
  eq(binarySearch([1, 3, 5, 7, 9], 5), 2);
});

test('binarySearch finds the first and last values', () => {
  eq(binarySearch([1, 3, 5, 7, 9], 1), 0);
  eq(binarySearch([1, 3, 5, 7, 9], 9), 4);
});

test('binarySearch returns -1 for a missing value', () => {
  eq(binarySearch([1, 3, 5], 4), -1);
  eq(binarySearch([1, 3, 5], 99), -1);
});

test('binarySearch handles empty and single-element arrays', () => {
  eq(binarySearch([], 1), -1);
  eq(binarySearch([2], 2), 0);
});

test('binarySearch scales to a thousand values', () => {
  const evens = Array.from({ length: 1000 }, (_, i) => i * 2);
  eq(binarySearch(evens, 998), 499);
  eq(binarySearch(evens, 999), -1);
});

test('searchInsert returns the index of an existing value', () => {
  eq(searchInsert([1, 3, 5, 6], 5), 2);
});

test('searchInsert points at the gap for a missing value', () => {
  eq(searchInsert([1, 3, 5, 6], 2), 1);
  eq(searchInsert([1, 3, 5, 6], 0), 0);
});

test('searchInsert can point past the end, and handles empty', () => {
  eq(searchInsert([1, 3, 5, 6], 7), 4);
  eq(searchInsert([], 3), 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('finds both ends of a run', () => {
  eq(firstOccurrence([5, 7, 7, 8, 8, 10], 8), 3);
  eq(lastOccurrence([5, 7, 7, 8, 8, 10], 8), 4);
});

test('returns -1 when the target is absent', () => {
  eq(firstOccurrence([5, 7, 7, 8, 8, 10], 6), -1);
  eq(lastOccurrence([5, 7, 7, 8, 8, 10], 6), -1);
});

test('handles an array that is all one value', () => {
  eq(firstOccurrence([2, 2, 2, 2], 2), 0);
  eq(lastOccurrence([2, 2, 2, 2], 2), 3);
});

test('handles a run that starts at index 0', () => {
  eq(firstOccurrence([1, 1, 2, 3], 1), 0);
  eq(lastOccurrence([1, 1, 2, 3], 1), 1);
});

test('handles a run that ends at the last index', () => {
  eq(firstOccurrence([1, 2, 3, 3], 3), 2);
  eq(lastOccurrence([1, 2, 3, 3], 3), 3);
});

test('handles single-element and empty arrays', () => {
  eq(firstOccurrence([2], 2), 0);
  eq(lastOccurrence([2], 3), -1);
  eq(firstOccurrence([], 1), -1);
});

test('stays fast on a huge run of duplicates', () => {
  const many = new Array(200000).fill(4);
  many[0] = 1;
  eq(firstOccurrence(many, 4), 1);
  eq(lastOccurrence(many, 4), 199999);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns the exact root of a perfect square', () => {
  eq(integerSqrt(16), 4);
  eq(integerSqrt(144), 12);
});

test('floors a non-perfect square', () => {
  eq(integerSqrt(8), 2);
  eq(integerSqrt(26), 5);
});

test('handles 0 and 1', () => {
  eq(integerSqrt(0), 0);
  eq(integerSqrt(1), 1);
});

test('handles the smallest non-trivial inputs', () => {
  eq(integerSqrt(2), 1);
  eq(integerSqrt(3), 1);
});

test('is right on either side of a perfect square', () => {
  eq(integerSqrt(999999), 999);
  eq(integerSqrt(1000000), 1000);
});

test('stays fast on a large number', () => {
  eq(integerSqrt(123456789), 11111);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('builds all 8 subsets of a 3-element array', () => {
  const expected = [[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]];
  eq(canon(subsets([1, 2, 3])), canon(expected));
});

test('the empty array has exactly one subset: the empty one', () => {
  eq(subsets([]), [[]]);
});

test('a single element gives the empty set and itself', () => {
  eq(canon(subsets(['a'])), canon([[], ['a']]));
});

test('subsets keep the original element order', () => {
  eq(canon(subsets(['a', 'b'])), ['', 'a', 'a,b', 'b']);
});

test('the count is 2 to the power of the input length', () => {
  eq(subsets([1, 2, 3, 4]).length, 16);
  eq(subsets([1, 2, 3, 4, 5]).length, 32);
});

test('every subset is distinct and is its own array', () => {
  const out = subsets([1, 2, 3]);
  eq(new Set(canon(out)).size, 8);
  ok(out[0] !== out[1], 'subsets must not share one array reference');
});

test('does not modify the input array', () => {
  const items = [1, 2, 3];
  subsets(items);
  eq(items, [1, 2, 3]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('produces every arrangement of three distinct characters', () => {
  eq(permutations('abc').sort(), ['abc', 'acb', 'bac', 'bca', 'cab', 'cba']);
});

test('produces n! results for distinct characters', () => {
  eq(permutations('abcd').length, 24);
  eq(permutations('abcde').length, 120);
});

test('drops duplicate arrangements when characters repeat', () => {
  eq(permutations('aab').sort(), ['aab', 'aba', 'baa']);
});

test('handles a single character', () => {
  eq(permutations('a'), ['a']);
});

test('the empty string has one arrangement: itself', () => {
  eq(permutations(''), ['']);
});

test('every result uses exactly the input characters', () => {
  const all = permutations('xyz');
  eq(all.length, 6);
  for (const p of all) {
    ok([...p].sort().join('') === 'xyz', `${p} is not a rearrangement`);
  }
});

test('results are unique even for an all-same string', () => {
  eq(permutations('aaa'), ['aaa']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('finds a path down the left branch', () => {
  eq(hasPathSum(tree, 20), true);
});

test('finds a path down the right branch', () => {
  eq(hasPathSum(tree, 26), true);
});

test('a path must end at a leaf, not part way down', () => {
  eq(hasPathSum(tree, 9), false);
});

test('returns false when no path adds up', () => {
  eq(hasPathSum(tree, 21), false);
});

test('handles negative values along the path', () => {
  eq(hasPathSum(tree, 11), true);
});

test('a missing node is not a path', () => {
  eq(hasPathSum(null, 0), false);
  eq(hasPathSum(undefined, 5), false);
});

test('handles a single-node tree', () => {
  const leaf = { value: 7, children: [] };
  eq(hasPathSum(leaf, 7), true);
  eq(hasPathSum(leaf, 0), false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sorts numbers ascending by default', () => {
  eq(insertionSort([5, 2, 4, 6, 1, 3]), [1, 2, 3, 4, 5, 6]);
});

test('handles empty and single-element arrays', () => {
  eq(insertionSort([]), []);
  eq(insertionSort([7]), [7]);
});

test('leaves an already sorted array alone', () => {
  eq(insertionSort([1, 2, 3]), [1, 2, 3]);
});

test('handles a reversed array and duplicates', () => {
  eq(insertionSort([3, 2, 1]), [1, 2, 3]);
  eq(insertionSort([2, 1, 2, 1]), [1, 1, 2, 2]);
});

test('honours a custom comparator', () => {
  eq(insertionSort([1, 3, 2], (a, b) => b - a), [3, 2, 1]);
});

test('is stable: ties keep their original order', () => {
  const rows = [
    { name: 'a', rank: 2 },
    { name: 'b', rank: 1 },
    { name: 'c', rank: 2 },
    { name: 'd', rank: 1 },
  ];
  const sorted = insertionSort(rows, (x, y) => x.rank - y.rank);
  eq(sorted.map((r) => r.name), ['b', 'd', 'a', 'c']);
});

test('sorts in place and returns the same array', () => {
  const nums = [3, 1, 2];
  ok(insertionSort(nums) === nums, 'should return the same array reference');
  eq(nums, [1, 2, 3]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sorts numbers ascending by default', () => {
  eq(mergeSort([5, 2, 9, 1, 5, 6]), [1, 2, 5, 5, 6, 9]);
});

test('handles empty, single-element and all-same arrays', () => {
  eq(mergeSort([]), []);
  eq(mergeSort([7]), [7]);
  eq(mergeSort([4, 4, 4]), [4, 4, 4]);
});

test('returns a new array and leaves the input untouched', () => {
  const nums = [3, 1, 2];
  const sorted = mergeSort(nums);
  ok(sorted !== nums, 'should not return the same array reference');
  eq(nums, [3, 1, 2]);
  eq(sorted, [1, 2, 3]);
});

test('handles odd lengths and reversed input', () => {
  eq(mergeSort([5, 4, 3, 2, 1]), [1, 2, 3, 4, 5]);
});

test('honours a custom comparator', () => {
  const words = ['ccc', 'a', 'bb'];
  eq(mergeSort(words, (x, y) => x.length - y.length), ['a', 'bb', 'ccc']);
});

test('is stable: ties keep their original order', () => {
  const rows = [
    { name: 'a', rank: 2 },
    { name: 'b', rank: 1 },
    { name: 'c', rank: 2 },
    { name: 'd', rank: 1 },
  ];
  const sorted = mergeSort(rows, (x, y) => x.rank - y.rank);
  eq(sorted.map((r) => r.name), ['b', 'd', 'a', 'c']);
});

test('sorts a hundred values without breaking a sweat', () => {
  const descending = Array.from({ length: 100 }, (_, i) => 99 - i);
  const expected = Array.from({ length: 100 }, (_, i) => i);
  eq(mergeSort(descending), expected);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sorts numbers ascending by default', () => {
  eq(quickSort([5, 2, 9, 1, 5, 6]), [1, 2, 5, 5, 6, 9]);
});

test('handles empty and single-element arrays', () => {
  eq(quickSort([]), []);
  eq(quickSort([7]), [7]);
});

test('survives an array where every value is the same', () => {
  eq(quickSort([7, 7, 7, 7, 7]), [7, 7, 7, 7, 7]);
});

test('handles already sorted and reversed input', () => {
  eq(quickSort([1, 2, 3, 4]), [1, 2, 3, 4]);
  eq(quickSort([4, 3, 2, 1]), [1, 2, 3, 4]);
});

test('handles duplicates mixed through the array', () => {
  eq(quickSort([3, 1, 3, 1, 2]), [1, 1, 2, 3, 3]);
});

test('honours a custom comparator', () => {
  eq(quickSort([1, 3, 2], (a, b) => b - a), [3, 2, 1]);
});

test('sorts in place and returns the same array', () => {
  const nums = [3, 1, 2];
  ok(quickSort(nums) === nums, 'should return the same array reference');
  eq(nums, [1, 2, 3]);
});

test('sorts two hundred values, worst-case ordering included', () => {
  const descending = Array.from({ length: 200 }, (_, i) => 199 - i);
  const expected = Array.from({ length: 200 }, (_, i) => i);
  eq(quickSort(descending), expected);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('encode collapses runs of repeats', () => {
  eq(encode('aaabbc'), 'a3b2c1');
});

test('encode writes a count of 1 for lone characters', () => {
  eq(encode('abc'), 'a1b1c1');
});

test('encode handles a run longer than nine', () => {
  eq(encode('zzzzzzzzzzzz'), 'z12');
});

test('encode handles empty text and one character', () => {
  eq(encode(''), '');
  eq(encode('q'), 'q1');
});

test('decode expands counts back into runs', () => {
  eq(decode('a3b2c1'), 'aaabbc');
});

test('decode reads multi-digit counts', () => {
  eq(decode('z12'), 'z'.repeat(12));
  eq(decode('a10b2'), 'aaaaaaaaaabb');
});

test('decode handles empty input', () => {
  eq(decode(''), '');
});

test('encode and decode round-trip', () => {
  const text = 'mississippi';
  eq(encode(text), 'm1i1s2i1s2i1p2i1');
  eq(decode(encode(text)), text);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('shifts lowercase letters forward', () => {
  eq(caesar('abc', 1), 'bcd');
});

test('wraps around the end of the alphabet', () => {
  eq(caesar('xyz', 3), 'abc');
});

test('preserves case and leaves punctuation alone', () => {
  eq(caesar('Hello, World!', 1), 'Ifmmp, Xpsme!');
  eq(caesar('a1!', 1), 'b1!');
});

test('a negative shift decodes', () => {
  eq(caesar('bcd', -1), 'abc');
  eq(caesar(caesar('Attack at dawn', 5), -5), 'Attack at dawn');
});

test('a shift bigger than 26 wraps', () => {
  eq(caesar('a', 27), 'b');
  eq(caesar('a', 0), 'a');
});

test('handles empty text', () => {
  eq(caesar('', 5), '');
});

test('rot13 shifts by thirteen', () => {
  eq(rot13('Hello'), 'Uryyb');
});

test('rot13 is its own inverse', () => {
  eq(rot13(rot13('Hello, World!')), 'Hello, World!');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('isSubsequence accepts characters spread through the text', () => {
  eq(isSubsequence('abc', 'ahbgdc'), true);
